def seed_metadata_types(apps, schema_editor):
    MetadataType = apps.get_model("api", "MetadataType")
    MetadataRecord = apps.get_model("api", "MetadataRecord")

    oceanography, _ = MetadataType.objects.get_or_create(metadata_type_value="Oceanography")
    MetadataType.objects.get_or_create(metadata_type_value="Drone")

    # Every record that exists today predates this field - all of it is
    # oceanographic data, per the user's own call.
    MetadataRecord.objects.filter(metadata_type__isnull=True).update(metadata_type=oceanography)


def unseed_metadata_types(apps, schema_editor):
    MetadataType = apps.get_model("api", "MetadataType")
    MetadataRecord = apps.get_model("api", "MetadataRecord")
    MetadataRecord.objects.all().update(metadata_type=None)
    MetadataType.objects.filter(metadata_type_value__in=["Oceanography", "Drone"]).delete()


