def seed_indexes(apps, schema_editor):
    MetadataType = apps.get_model("api", "MetadataType")
    ElasticsearchIndex = apps.get_model("api", "ElasticsearchIndex")
    ElasticsearchFieldMap = apps.get_model("api", "ElasticsearchFieldMap")

    for type_value, index_name in [("Oceanography", "oceanography"), ("Drone", "drone")]:
        metadata_type = MetadataType.objects.get(metadata_type_value=type_value)
        index, _ = ElasticsearchIndex.objects.get_or_create(
            metadata_type=metadata_type,
            defaults={"name": type_value, "index_name": index_name},
        )
        for order, (source, target, es_type) in enumerate(DEFAULT_FIELDS):
            ElasticsearchFieldMap.objects.get_or_create(
                index=index,
                source=source,
                defaults={"target": target, "es_type": es_type, "order": order},
            )


def unseed_indexes(apps, schema_editor):
    ElasticsearchIndex = apps.get_model("api", "ElasticsearchIndex")
    ElasticsearchIndex.objects.filter(name__in=["Oceanography", "Drone"]).delete()


BOUNDING_BOX_FIELDS = [
    ("west_bound_longitude", "west_bounding_longitude", "float"),
    ("east_bound_longitude", "east_bounding_longitude", "float"),
    ("south_bound_latitude", "south_bounding_latitude", "float"),
    ("north_bound_latitude", "north_bounding_latitude", "float"),
]


def add_bounding_box_fields(apps, schema_editor):
    ElasticsearchIndex = apps.get_model("api", "ElasticsearchIndex")
    ElasticsearchFieldMap = apps.get_model("api", "ElasticsearchFieldMap")

    for index in ElasticsearchIndex.objects.all():
        for offset, (source, target, es_type) in enumerate(BOUNDING_BOX_FIELDS):
            ElasticsearchFieldMap.objects.get_or_create(
                index=index,
                source=source,
                defaults={"target": target, "es_type": es_type, "order": 100 + offset},
            )


def remove_bounding_box_fields(apps, schema_editor):
    ElasticsearchFieldMap = apps.get_model("api", "ElasticsearchFieldMap")
    ElasticsearchFieldMap.objects.filter(
        source__in=[source for source, _, _ in BOUNDING_BOX_FIELDS]
    ).delete()


